package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Membership points contributed by the owner having an email address. One factor of the
 * overall {@link MembershipPoints} total; owns the "has an email" test and its weight.
 */
public final class EmailFactor {

    private static final int POINTS = 1;

    private EmailFactor() {
    }

    public static int points(Owner owner) {
        return present(owner) ? POINTS : 0;
    }

    private static boolean present(Owner owner) {
        return owner.getEmail() != null && !owner.getEmail().isBlank();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Membership points contributed by the owner's tenure exceeding the qualifying threshold
 * of 365 days. One factor of the overall {@link MembershipPoints} total; owns the tenure
 * test, its threshold and its weight. A newly created owner has zero tenure.
 */
public final class TenureFactor {

    private static final int POINTS = 1;

    private static final long TENURE_DAYS = 365;

    private TenureFactor() {
    }

    public static int points(Owner owner) {
        return qualifies(owner) ? POINTS : 0;
    }

    private static boolean qualifies(Owner owner) {
        LocalDate registered = owner.getRegistrationDate();
        return registered != null && ChronoUnit.DAYS.between(registered, LocalDate.now()) > TENURE_DAYS;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Aggregate membership points for an owner: a starting allowance plus the points
 * contributed by each qualifying factor. Adding or reweighting a factor is a change to a
 * single small factor class ({@link EmailFactor}, {@link NamesakeFactor},
 * {@link TenureFactor}) or to this sum, not to the level-mapping in {@link MembershipLevel}.
 */
public final class MembershipPoints {

    private static final int BASE = 1;

    private MembershipPoints() {
    }

    public static int of(Owner owner) {
        return BASE + EmailFactor.points(owner) + NamesakeFactor.points(owner) + TenureFactor.points(owner);
    }
}

